def make_pair(h,w,bg,frames):
    g=[[bg]*w for _ in range(h)]; expected=[[bg]*w for _ in range(h)]
    for r,c,n,color,fill in frames:
        for y in range(r,r+n):
            for x in range(c,c+n):
                if y in (r,r+n-1) or x in (c,c+n-1):
                    g[y][x]=expected[y][x]=color
                else:
                    expected[y][x]=fill
    return g,expected
# Coordinates and expected fill values read from the two received demonstration pairs.
